import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2024-10-9","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2024-10-9","date":"2024-10-24T00:00:00.000Z","updated":"2024-10-25T00:00:00.000Z","tags":["Ceph","RGW","并行重分片","协程","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-9.md","filePath":"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-9.md","lastUpdated":1780459816000}'),r={name:"posts/2024/Ceph_RGW_Refactoring_Meeting_2024-10-9.md"};function o(n,a,h,s,c,d){return l(),i("div",null,[...a[0]||(a[0]=[t('<h3 id="ceph-rgw重构会议纪要-2024-10-9" tabindex="-1">Ceph RGW重构会议纪要 2024-10-9 <a class="header-anchor" href="#ceph-rgw重构会议纪要-2024-10-9" aria-label="Permalink to &quot;Ceph RGW重构会议纪要 2024-10-9&quot;">​</a></h3><h4 id="会议主题-并行重分片设计讨论" tabindex="-1">会议主题：并行重分片设计讨论 <a class="header-anchor" href="#会议主题-并行重分片设计讨论" aria-label="Permalink to &quot;会议主题：并行重分片设计讨论&quot;">​</a></h4><h4 id="参会人员-ceph-研发团队成员" tabindex="-1">参会人员：Ceph 研发团队成员 <a class="header-anchor" href="#参会人员-ceph-研发团队成员" aria-label="Permalink to &quot;参会人员：Ceph 研发团队成员&quot;">​</a></h4><h4 id="会议时间-2024年10月9日" tabindex="-1">会议时间：2024年10月9日 <a class="header-anchor" href="#会议时间-2024年10月9日" aria-label="Permalink to &quot;会议时间：2024年10月9日&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>并行重分片设计</strong>：</p><ul><li>讨论了并行重分片设计的进展，特别是Mingan Leang之前的工作。</li><li>探讨了使用C++ 20的stackless协程或现有的协程（带可选yield）的方案。</li><li>分析了两种方案的不足之处，特别是关于元数据处理的复杂性。</li></ul></li><li><p><strong>协程选择</strong>：</p><ul><li>讨论了是否采用C++ 20协程，以及如何管理代码复杂性和避免代码重复。</li><li>探讨了从现有协程迁移到C++ 20协程的可行性和策略。</li></ul></li><li><p><strong>具体实现问题</strong>：</p><ul><li>讨论了如何处理元数据同步中的协程调用问题，特别是在RGW管理命令中的同步问题。</li><li>提出了逐步迁移的策略，从底层系统对象开始，逐步向上迁移。</li></ul></li><li><p><strong>其他相关议题</strong>：</p><ul><li>讨论了跨区域复制的问题，特别是如何处理多个规则的桶复制。</li><li>讨论了删除过程的问题，特别是在多区域组中的桶删除问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>决定暂时采用stackful协程进行并行重分片设计，未来再考虑迁移到C++ 20协程。</li><li>同意逐步迁移的策略，从底层系统对象开始，逐步向上迁移。</li><li>将重新启用多区域组测试，以确保进一步的更改不会引入新的问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>更新并行重分片设计文档，明确采用stackful协程的方案。</li><li>开始逐步迁移工作，从系统对象开始，逐步向上迁移。</li><li>重新启用多区域组测试，确保代码的稳定性和兼容性。</li><li>继续讨论和解决跨区域复制和删除过程的具体问题。</li></ul><h4 id="其他讨论" tabindex="-1">其他讨论： <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论：&quot;">​</a></h4><ul><li>讨论了在同一RGW实例中托管多个区域的可能性，以及这种设计的潜在优势和问题。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，团队成员将继续跟进各自的任务和问题。</li></ul><p><strong>注意</strong>：本次会议纪要涵盖了会议的关键细节、讨论的主要议题、决定的事项以及后续的行动计划，并保留了计算机科学/ceph相关领域的英文原文关键词，以确保信息的准确性和专业性。</p>',16)])])}const _=e(r,[["render",o]]);export{p as __pageData,_ as default};
